  `work_date` date NOT NULL,
  `day_type` enum('WORKDAY','HOLIDAY','OFF') DEFAULT 'WORKDAY',
  `overtime_type` enum('REGULAR','FIXED') NOT NULL,
  `early_start` datetime DEFAULT NULL,
  `early_end` datetime DEFAULT NULL,
  `late_start` datetime DEFAULT NULL,
  `late_end` datetime DEFAULT NULL,
  `holiday_start` datetime DEFAULT NULL,
  `holiday_end` datetime DEFAULT NULL,
  `early_hours` decimal(5,2) DEFAULT 0.00,
