  `holiday_hours` decimal(5,2) DEFAULT 0.00,
  `total_hours` decimal(5,2) DEFAULT 0.00,
  `total_hours_actual` decimal(5,2) DEFAULT 0.00 COMMENT 'Jam lembur aktual tanpa pembulatan',
  `overtime_index` decimal(8,2) DEFAULT 0.00,
  `shift_id` bigint(20) DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_date` (`employee_id`,`work_date`),
  CONSTRAINT `trn_overtime_mst_employee_FK` FOREIGN KEY (`employee_id`) REFERENCES `mst_employee` (`employee_id`)
