/*!50003 DROP PROCEDURE IF EXISTS `sp_payroll_recapitulation` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'IGNORE_SPACE,STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_payroll_recapitulation`(
    IN p_period_id INT,
    IN p_company_id VARCHAR(50)
)
BEGIN

    DECLARE cols_emp_plus TEXT;
    DECLARE cols_emp_minus TEXT;
    DECLARE cols_comp_plus TEXT;
    DECLARE cols_comp_minus TEXT;

    /*
    |--------------------------------------------------------------------------
    | EMP (+)
    |--------------------------------------------------------------------------
    */
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MAX(
                CASE 
                    WHEN component_code = ''',
                    component_code,
                    ''' 
                    THEN IFNULL(amount,0)
                END
            ) AS `',
            REPLACE(allowance_name, '`', ''),
            '`'
        )
        ORDER BY sort ASC
    ) INTO cols_emp_plus
    FROM vw_payroll_process
    WHERE period_id = p_period_id
    AND calc_for = 'emp'
    AND type = '+';


    /*
    |--------------------------------------------------------------------------
    | EMP (-)
    |--------------------------------------------------------------------------
    */
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MAX(
                CASE 
                    WHEN component_code = ''',
                    component_code,
                    ''' 
                    THEN IFNULL(amount,0)
                END
            ) AS `',
            REPLACE(allowance_name, '`', ''),
            '`'
        )
        ORDER BY sort ASC
    ) INTO cols_emp_minus
    FROM vw_payroll_process
    WHERE period_id = p_period_id
    AND calc_for = 'emp'
    AND type = '-';


    /*
    |--------------------------------------------------------------------------
    | COMP (+)
    |--------------------------------------------------------------------------
    */
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MAX(
                CASE 
                    WHEN component_code = ''',
                    component_code,
                    ''' 
                    THEN IFNULL(amount,0)
                END
            ) AS `',
            REPLACE(allowance_name, '`', ''),
            '`'
        )
        ORDER BY sort ASC
    ) INTO cols_comp_plus
    FROM vw_payroll_process
    WHERE period_id = p_period_id
    AND calc_for = 'comp'
    AND type = '+';


    /*
    |--------------------------------------------------------------------------
    | COMP (-)
    |--------------------------------------------------------------------------
    */
    SELECT GROUP_CONCAT(
        DISTINCT CONCAT(
            'MAX(
                CASE 
                    WHEN component_code = ''',
                    component_code,
                    ''' 
                    THEN IFNULL(amount,0)
                END
            ) AS `',
            REPLACE(allowance_name, '`', ''),
            '`'
        )
        ORDER BY sort ASC
    ) INTO cols_comp_minus
    FROM vw_payroll_process
    WHERE period_id = p_period_id
    AND calc_for = 'comp'
    AND type = '-';


    /*
    |--------------------------------------------------------------------------
    | Main Query
    |--------------------------------------------------------------------------
    */
    SET @sql = CONCAT(
        '
        SELECT
            employee_name as Name,
            employee_code as Noreg,
            position_name as Position,
            company_name as Company,
			ptkp_code as PTKP,
			working_name AS `Working Status`,
			bank_name AS `Bank Name`,
			account_number_bank AS `Number Account` ,

            -- EMP (+)
            ',
            IFNULL(cols_emp_plus, ''),
            ',

            -- TOTAL EARNING
            SUM(
                CASE 
                    WHEN type = ''+''
                    AND calc_for = ''emp''
                    THEN IFNULL(amount,0)
                    ELSE 0
                END
            ) AS `Total Earning`,

            -- EMP (-)
            ',
            IFNULL(cols_emp_minus, ''),
            ',

            -- TOTAL DEDUCTION
            SUM(
                CASE 
                    WHEN type = ''-''
                    AND calc_for = ''emp''
                    THEN IFNULL(amount,0)
                    ELSE 0
                END
            ) AS `Total Deduction`,

            -- COMP (+)
            ',
            IFNULL(cols_comp_plus, ''),
            IF(
                cols_comp_minus IS NOT NULL 
                AND cols_comp_minus <> '',
                CONCAT(',', cols_comp_minus),
                ''
            ),
            ',

            -- TAKE HOME PAY
            (
                SUM(
                    CASE 
                        WHEN type = ''+''
                        AND calc_for = ''emp''
                        THEN IFNULL(amount,0)
                        ELSE 0
                    END
                )
                -
                SUM(
                    CASE 
                        WHEN type = ''-''
                        AND calc_for = ''emp''
                        THEN IFNULL(amount,0)
                        ELSE 0
                    END
                )
            ) AS `Take HomePay`

        FROM vw_payroll_process

        WHERE period_id = ', p_period_id
    );


    /*
    |--------------------------------------------------------------------------
    | Optional Company Filter
    |--------------------------------------------------------------------------
    */
    IF p_company_id IS NOT NULL 
       AND p_company_id <> '' THEN

        SET @sql = CONCAT(
            @sql,
            ' AND company_id = ''',
            p_company_id,
            ''' '
        );

    END IF;


    /*
    |--------------------------------------------------------------------------
    | Grouping
    |--------------------------------------------------------------------------
    */
    SET @sql = CONCAT(
        @sql,
        '
        GROUP BY
            employee_id,
            employee_name,
            employee_code,
            position_name,
            company_name,
            bank_name,
            account_number_bank
			
        ORDER BY employee_name ASC
        '
    );


    /*
    |--------------------------------------------------------------------------
    | Execute
    |--------------------------------------------------------------------------
    */
    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_unpost_payroll` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'IGNORE_SPACE,STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_unpost_payroll`(IN p_period_id INT, IN p_employee_id BIGINT)
begin

	-- delete all payroll
	delete from payroll_employee_component where period_id = p_period_id and employee_id=p_employee_id;
	delete from payroll_employee_tax where period_id = p_period_id and employee_id=p_employee_id;
	
end ;;
